<?php require __DIR__.'/bootstrap.php'; if(session_status()!==PHP_SESSION_ACTIVE)session_start(); $cart=$_SESSION['cart']??[]; $products=read_json('products.json',[]); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); if(($_POST['action']??'')==='add'){ $id=(string)($_POST['product_id']??'');$p=null;foreach($products as $x)if($x['id']===$id&&!empty($x['available'])){$p=$x;break;} if(!$p){$message='This product is unavailable.';}else{$sizeLabel=(string)($_POST['size']??'');$size=null;foreach(($p['sizes']??[]) as $s)if($s['label']===$sizeLabel){$size=$s;break;} $flavourLabel=(string)($_POST['flavour']??'');$flavour=null;foreach(($p['flavours']??[]) as $f)if($f['label']===$flavourLabel){$flavour=$f;break;} $custom=trim((string)($_POST['custom_message']??''));$qty=max(1,min(20,(int)($_POST['qty']??1)));if(!$size||!$flavour||$custom===''){$message='Please choose valid options and enter the required custom message.';}else{$unit=(float)$size['price']+(float)($flavour['extra']??0);$cart[]=['cart_id'=>bin2hex(random_bytes(5)),'product_id'=>$id,'name'=>$p['name'],'image'=>$p['image'],'size'=>$sizeLabel,'flavour'=>$flavourLabel,'qty'=>$qty,'custom_message'=>$custom,'occasion'=>trim((string)($_POST['occasion']??'')),'instructions'=>trim((string)($_POST['instructions']??'')),'additional'=>trim((string)($_POST['additional']??'')),'unit_price'=>$unit,'line_total'=>$unit*$qty];$_SESSION['cart']=$cart;redirect('cart.php?added=1');}}} elseif(($_POST['action']??'')==='remove'){ $cart=array_values(array_filter($cart,fn($i)=>$i['cart_id']!==(string)($_POST['cart_id']??'')));$_SESSION['cart']=$cart;redirect('cart.php');} elseif(($_POST['action']??'')==='update'){foreach($cart as &$i){$q=max(1,min(20,(int)($_POST['qty'][$i['cart_id']]??$i['qty'])));$i['qty']=$q;$i['line_total']=$q*$i['unit_price'];}unset($i);$_SESSION['cart']=$cart;redirect('cart.php');}} $subtotal=array_sum(array_map(fn($i)=>(float)$i['line_total'],$cart)); site_header('Your cart'); ?>
<section class="page-hero"><div class="eyebrow">Almost something sweet</div><h1>Your shopping cart.</h1><p>Review each cake and its personal details before checkout.</p></section><section class="content"><?php if(isset($_GET['added']))echo '<div class="alert success">Cake added to your cart.</div>';if($message)echo '<div class="alert error">'.e($message).'</div>';if(!$cart): ?><div class="empty-state"><h2>Your cart is waiting for something lovely.</h2><p>Explore the collection and find a cake for your moment.</p><a class="button" href="cakes.php">Shop cakes</a></div><?php else: ?><div class="cart-layout"><div class="card-panel"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update"><div class="table-wrap"><table class="data-table"><thead><tr><th>Cake</th><th>Qty</th><th>Amount</th><th></th></tr></thead><tbody><?php foreach($cart as $i): ?><tr><td><strong><?= e($i['name']) ?></strong><br><small><?= e($i['size']) ?> · <?= e($i['flavour']) ?></small><br><small>Message: <?= e($i['custom_message']) ?></small><?php if($i['instructions']): ?><br><small>Notes: <?= e($i['instructions']) ?></small><?php endif; ?></td><td><input class="qty" type="number" name="qty[<?= e($i['cart_id']) ?>]" value="<?= (int)$i['qty'] ?>" min="1" max="20"></td><td><?= money((float)$i['line_total']) ?></td><td><button class="text-link" form="remove-<?= e($i['cart_id']) ?>" type="submit">Remove</button></td></tr><?php endforeach; ?></tbody></table></div><p><button class="button button-outline" type="submit">Update quantities</button></p></form><?php foreach($cart as $i): ?><form id="remove-<?= e($i['cart_id']) ?>" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="cart_id" value="<?= e($i['cart_id']) ?>"></form><?php endforeach; ?></div><aside class="card-panel"><h2>Order summary</h2><div class="summary-row"><span>Subtotal</span><strong><?= money($subtotal) ?></strong></div><div class="summary-row"><span>Delivery</span><span>Calculated at checkout</span></div><div class="summary-row total"><span>Subtotal</span><span><?= money($subtotal) ?></span></div><p class="muted">Choose delivery or pickup at checkout. Delivery fees depend on the approved area.</p><a class="button" style="width:100%" href="checkout.php">Continue to checkout ↗</a><p class="muted">Secure payment powered by Paystack.</p></aside></div><?php endif; ?></section><?php site_footer(); ?>
